-- Dictation sentences extracted from Vocable Anglais (Mars & Juillet 2025)
-- Source: Bilingual articles (News Digest, pages 3-6 of each issue)

INSERT INTO dictation_sentences (text, translation_fr, difficulty, category) VALUES
-- Mars 2025 - p03: AI in Healthcare: A New Era
('Artificial intelligence is revolutionising the field of healthcare, offering new possibilities for diagnosis and treatment.', 'L''intelligence artificielle révolutionne le domaine de la santé, offrant de nouvelles possibilités pour le diagnostic et le traitement.', 'B2', 'technologie'),
('AI-powered tools can now analyse medical images with remarkable precision, helping doctors detect diseases at an early stage.', 'Les outils alimentés par l''IA peuvent désormais analyser des images médicales avec une précision remarquable, aidant les médecins à détecter les maladies à un stade précoce.', 'B2', 'technologie'),
('However, concerns remain about data privacy and the need for human oversight in medical decision-making.', 'Cependant, des préoccupations subsistent quant à la confidentialité des données et à la nécessité d''une supervision humaine dans les décisions médicales.', 'B2', 'technologie'),
-- Mars 2025 - p04: Climate Policy: Global Efforts
('World leaders gathered at the climate summit to discuss ambitious targets for reducing greenhouse gas emissions.', 'Les dirigeants du monde entier se sont réunis au sommet climatique pour discuter d''objectifs ambitieux de réduction des émissions de gaz à effet de serre.', 'B2', 'environnement'),
('Many countries have pledged to achieve carbon neutrality by twenty-fifty, investing heavily in renewable energy.', 'De nombreux pays se sont engagés à atteindre la neutralité carbone d''ici 2050, en investissant massivement dans les énergies renouvelables.', 'B2', 'environnement'),
('The transition to clean energy is accelerating, but experts warn that more action is needed to limit global warming.', 'La transition vers les énergies propres s''accélère, mais les experts avertissent que des actions supplémentaires sont nécessaires pour limiter le réchauffement climatique.', 'B2', 'environnement'),
-- Mars 2025 - p05: Space Exploration: The Next Frontier
('The new space mission aims to send astronauts to Mars within the next decade, marking a new era in space exploration.', 'La nouvelle mission spatiale vise à envoyer des astronautes sur Mars dans la prochaine décennie, marquant une nouvelle ère dans l''exploration spatiale.', 'B2', 'science'),
('Space agencies are developing advanced technologies that could sustain human life on other planets.', 'Les agences spatiales développent des technologies avancées qui pourraient maintenir la vie humaine sur d''autres planètes.', 'B2', 'science'),
('The discovery of water on Mars has raised hopes that one day humans could colonise the red planet.', 'La découverte d''eau sur Mars a suscité l''espoir qu''un jour, les humains pourraient coloniser la planète rouge.', 'B2', 'science'),
-- Mars 2025 - p06: European Politics: Unity and Challenges
('The European Union faces new challenges as member states debate future policies on migration and economic reform.', 'L''Union européenne fait face à de nouveaux défis alors que les États membres débattent des futures politiques sur la migration et la réforme économique.', 'B2', 'politique'),
('The recent elections have shifted the balance of power, raising questions about the future direction of the union.', 'Les récentes élections ont modifié l''équilibre des pouvoirs, soulevant des questions sur la direction future de l''union.', 'B2', 'politique'),
-- Juillet 2025 - p03: Remote Work Revolution
('The shift towards remote work has transformed the traditional office, with many companies adopting hybrid models.', 'Le passage au télétravail a transformé le bureau traditionnel, de nombreuses entreprises adoptant des modèles hybrides.', 'B2', 'travail'),
('Employees appreciate the flexibility of working from home, but some miss the social interaction of the office.', 'Les employés apprécient la flexibilité du télétravail, mais certains regrettent les interactions sociales du bureau.', 'B1', 'travail'),
('Studies show that remote workers are often more productive, but maintaining team cohesion remains a challenge.', 'Des études montrent que les télétravailleurs sont souvent plus productifs, mais maintenir la cohésion d''équipe reste un défi.', 'B2', 'travail'),
-- Juillet 2025 - p04: Olympic Games: Paris Legacy
('The Olympic Games in Paris left a lasting legacy, inspiring a new generation of athletes and promoting sports participation.', 'Les Jeux Olympiques de Paris ont laissé un héritage durable, inspirant une nouvelle génération d''athlètes et promouvant la participation sportive.', 'B2', 'sport'),
('The infrastructure built for the games will be used by local communities for years to come.', 'Les infrastructures construites pour les Jeux seront utilisées par les communautés locales pendant des années.', 'B1', 'sport'),
-- Juillet 2025 - p05: Digital Education: Learning Beyond Classrooms
('Digital technology has opened up new possibilities for education, allowing students to learn beyond the traditional classroom.', 'La technologie numérique a ouvert de nouvelles possibilités pour l''éducation, permettant aux élèves d''apprendre au-delà de la salle de classe traditionnelle.', 'B2', 'education'),
('Online platforms offer interactive courses that adapt to each student''s pace and learning style.', 'Les plateformes en ligne proposent des cours interactifs qui s''adaptent au rythme et au style d''apprentissage de chaque élève.', 'B1', 'education'),
('However, the digital divide remains a challenge, as not all students have access to the necessary technology.', 'Cependant, la fracture numérique reste un défi, car tous les élèves n''ont pas accès à la technologie nécessaire.', 'B2', 'education'),
-- Juillet 2025 - p06: Sustainable Tourism: Traveling Responsibly
('Sustainable tourism aims to minimise the environmental impact of travel while supporting local communities.', 'Le tourisme durable vise à minimiser l''impact environnemental des voyages tout en soutenant les communautés locales.', 'B2', 'voyage'),
('Travellers are increasingly choosing eco-friendly accommodations and transportation options.', 'Les voyageurs choisissent de plus en plus des hébergements et des options de transport respectueux de l''environnement.', 'B1', 'voyage'),
('Popular destinations are implementing measures to limit overcrowding and protect natural resources.', 'Les destinations populaires mettent en place des mesures pour limiter la surfréquentation et protéger les ressources naturelles.', 'B2', 'voyage');
